INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10101, '1 Chronicles 13:2', '1 Chronicles', 13, 2, '&nbsp;بيا هغۀ ټولو بنى اِسرائيلو ته اِعلان وکړو چې، ”کۀ تاسو ته منظوره وى او کۀ دا د مالِک خُدائ زمونږ د خُدائ پاک رضا وى، نو راځئ چې زمونږ باقى خلقو له او د هغوئ په ښارونو کښې اِمامانو او ليويانو له پېغام وړُونکى ولېږُو او هغوئ ته ووايو چې دلته مونږ سره راغونډ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10102, '1 Chronicles 13:3', '1 Chronicles', 13, 3, '&nbsp;نو بيا به مونږ لاړ شُو او د خُدائ پاک د لوظ صندوق به راوړُو، چې د ساؤل بادشاه په وخت کښې ورته توجو نۀ وه شوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10103, '1 Chronicles 13:4', '1 Chronicles', 13, 4, '&nbsp;ټول خلق دې ته راضى شول، ځکه چې خلقو ته پته ولګېده چې دا خبره صحيح ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10104, '1 Chronicles 13:5', '1 Chronicles', 13, 5, '&nbsp;نو داؤد د ټول مُلک نه بنى اِسرائيليان راغونډ کړل، په جنوب کښې د مِصر د سرحد نه واخله په شمال کښې د حمات درې پورې، د دې دپاره چې د لوظ صندوق د قِريَت‌يعريم نه يروشلم ته راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10105, '1 Chronicles 13:6', '1 Chronicles', 13, 6, '&nbsp;داؤد او نور ټول بنى اِسرائيليان د بعله يعنې قِريَت‌يعريم ښار ته لاړل چې د يهوداه په علاقه کښې دے، د دې دپاره چې د خُدائ پاک د لوظ صندوق راوړى، هغه صندوق چې د مالِک خُدائ په نوم ياديږى چې هغه د وزرو والا مخلوق په مينځ کښې په تخت باندې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10106, '1 Chronicles 13:7', '1 Chronicles', 13, 7, '&nbsp;د ابينداب د کور نه هغوئ د لوظ صندوق راوويستلو او په يوه نوې ګاډۍ باندې يې کېښودو. عُزه او اخيو د ګاډۍ لارښودنه کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10107, '1 Chronicles 13:8', '1 Chronicles', 13, 8, '&nbsp;په دې دوران کښې داؤد او ټول خلق د خپل ټول طاقت سره د خُدائ پاک د درناوى دپاره ګډېدل. سندرې يې وئيلې او ربابُونه، تمبلونه، چمټې او بيګلې يې غږولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10108, '1 Chronicles 13:9', '1 Chronicles', 13, 9, '&nbsp;کله چې هغوئ د کيدون درمند ته راغلل، نو غوَيانو تيندک وخوړو، عُزه خپل لاس وراوږد کړو او د لوظ صندوق يې رايسار کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10109, '1 Chronicles 13:10', '1 Chronicles', 13, 10, '&nbsp;نو مالِک خُدائ سمدستى عُزه ته غصه شو او صندوق له د لاس د وړلو په وجه يې ووژلو. هغه هلته د خُدائ پاک په حضور کښې مړ شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10110, '1 Chronicles 13:11', '1 Chronicles', 13, 11, '&nbsp;داؤد په قهر وو ځکه چې مالِک خُدائ عُزه له په غصه کښې سزا ورکړې وه. نو هغه ځائ تر اوسه پورې فارص‌عُزه بللے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10111, '1 Chronicles 13:12', '1 Chronicles', 13, 12, '&nbsp;بيا داؤد د خُدائ پاک نه ويرېدو او وې فرمائيل، ”زۀ اوس د لوظ صندوق څنګه د ځان سره يوسم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10112, '1 Chronicles 13:13', '1 Chronicles', 13, 13, '&nbsp;نو داؤد دا د ځان سره په يروشلم کښې د داؤد ښار ته يو نۀ وړو. د هغې په ځائ دا يې د يو سړى په کور کښې پرېښودو چې نوم يې عوبيد ادوم وو، چې د جات ښار نه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10113, '1 Chronicles 13:14', '1 Chronicles', 13, 14, '&nbsp;دا هلته درې مياشتې پاتې شو او مالِک خُدائ د عوبيد ادوم خاندان او هغه هر څۀ له برکت ورکړو چې د هغۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10114, '1 Chronicles 14:1', '1 Chronicles', 14, 1, '&nbsp;د صور بادشاه حيرام داؤد له پېغام وړُونکى ولېږل، هغۀ ورله د دِيار د لرګو سره د کاڼو، ګِلکارانو او ترکاڼانو بندوبست وکړو چې يو محل جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10115, '1 Chronicles 14:2', '1 Chronicles', 14, 2, '&nbsp;نو داؤد ته پته ولګېده چې مالِک خُدائ هغه د بنى اِسرائيلو بادشاه جوړ کړے دے او د خپلو خلقو په خاطر يې د هغۀ بادشاهۍ له برکت ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10116, '1 Chronicles 14:3', '1 Chronicles', 14, 3, '&nbsp;هلته په يروشلم کښې داؤد نورې ښځې وادۀ کړې او نور زامن او لوڼه يې پېدا شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10117, '1 Chronicles 14:4', '1 Chronicles', 14, 4, '&nbsp;د هغۀ دا بچى په يروشلم کښې پېدا شوى وُو: سموع، سوباب، ناتن، سليمان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10118, '1 Chronicles 14:5', '1 Chronicles', 14, 5, '&nbsp;اِبحار، اليسوع، الفالط،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10119, '1 Chronicles 14:6', '1 Chronicles', 14, 6, '&nbsp;نجه، نفج، يفيع،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10120, '1 Chronicles 14:7', '1 Chronicles', 14, 7, '&nbsp;اليسمع، بعليدع او اليفلط.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10121, '1 Chronicles 14:8', '1 Chronicles', 14, 8, '&nbsp;کله چې فلستيان خبر شول چې هغه د بنى اِسرائيل په ټول مُلک باندې بادشاه جوړ شوے دے، نو د هغوئ ټول لښکر د هغۀ د نيولو دپاره لاړو. او داؤد د هغوئ سره جنګ له روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10122, '1 Chronicles 14:9', '1 Chronicles', 14, 9, '&nbsp;فلستيان د رفائيم وادۍ ته رسېدلى وُو او لوټ مار يې شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10123, '1 Chronicles 14:10', '1 Chronicles', 14, 10, '&nbsp;داؤد د خُدائ پاک نه تپوس وکړو، ”ما له په فلستيانو باندې حمله کول په کار دى څۀ؟ تۀ به ما له فتح راکړې؟“ مالِک خُدائ جواب ورکړو، ”آو، حمله پرې وکړه. زۀ به تا له فتح درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10124, '1 Chronicles 14:11', '1 Chronicles', 14, 11, '&nbsp;نو داؤد په بعل‌پراضيم کښې په هغوئ باندې حمله وکړه او شکست يې ورکړو. هغۀ وفرمائيل، ”خُدائ پاک زۀ د سېلاب په شان استعمال کړے يم چې د دشمن لښکر په مخه يوسم.“ نو په دې وجه د هغه ځائ نوم بعل‌پراضيم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10125, '1 Chronicles 14:12', '1 Chronicles', 14, 12, '&nbsp;کله چې فلستيان تښتېدل، نو هغوئ خپل بُتان د ځان نه وروستو پرېښودل او داؤد حُکم وکړو چې دا دې وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10126, '1 Chronicles 14:13', '1 Chronicles', 14, 13, '&nbsp;خو لږ وخت پس فلستيان وادۍ ته راواپس شول او لوټ مار يې شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10127, '1 Chronicles 14:14', '1 Chronicles', 14, 14, '&nbsp;داؤد يو ځل بيا د خُدائ پاک سره مشوره وکړه او خُدائ پاک جواب ورکړو، ”په هغوئ باندې د دې ځائ نه حمله مۀ کوه، خو ورله راتاو شه او د بل طرف نه ورباندې د حملې کولو تيارے وکړه، چرته چې د تُوت ونې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10128, '1 Chronicles 14:15', '1 Chronicles', 14, 15, '&nbsp;کله چې د ونو په سرونو د تګ آواز واورې، نو بيا حمله وکړه، زۀ به ستاسو نه مخکښې د دې دپاره روان يم چې د فلستيانو لښکر له شکست ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10129, '1 Chronicles 14:16', '1 Chronicles', 14, 16, '&nbsp;نو داؤد هم هغه شان وکړل چې څنګه خُدائ پاک حُکم ورکړے وو او هغه د جبعون نه تر جزر پورې په فلستيانو پسې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10130, '1 Chronicles 14:17', '1 Chronicles', 14, 17, '&nbsp;د داؤد شُهرت په هر ځائ کښې خور شو او مالِک خُدائ ټول قومونه د هغۀ نه يرول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10131, '1 Chronicles 15:1', '1 Chronicles', 15, 1, '&nbsp;داؤد د ځان دپاره د داؤد په ښار کښې کورونه جوړ کړل. هغۀ د خُدائ پاک د لوظ صندوق دپاره هم يو ځائ تيار کړو او د دې دپاره يې يوه خېمه ودروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10132, '1 Chronicles 15:2', '1 Chronicles', 15, 2, '&nbsp;بيا هغۀ وفرمائيل، ”صِرف ليويان به د لوظ صندوق وړى، ځکه چې هغوئ هغه څوک دى چې مالِک خُدائ د دې د وړلو دپاره خوښ کړى دى او چې د همېشه دپاره د هغۀ خِدمت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10133, '1 Chronicles 15:3', '1 Chronicles', 15, 3, '&nbsp;نو داؤد ټول بنى اِسرائيليان د دې دپاره راغونډ کړل چې د لوظ صندوق هغه ځائ ته راوړى چې کوم يې ورله تيار کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10134, '1 Chronicles 15:4', '1 Chronicles', 15, 4, '&nbsp;نو بيا هغۀ د هارون اولاد او ليويانو راوغوښتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10135, '1 Chronicles 15:5', '1 Chronicles', 15, 5, '&nbsp;د قُهات د قبيلې اورى‌اېل خوښ کړے شو، چې د خپلې قبيلې د يو سل او شلو کسانو مشر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10136, '1 Chronicles 15:6', '1 Chronicles', 15, 6, '&nbsp;د مرارى قبيلې نه عساياه، چې د خپلې قبيلې د دوو سوو او شلو کسانو مشر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10137, '1 Chronicles 15:7', '1 Chronicles', 15, 7, '&nbsp;د جيرسون قبيلې نه يوايل، چې د خپلې قبيلې د يو سل او دېرشو کسانو مشر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10138, '1 Chronicles 15:8', '1 Chronicles', 15, 8, '&nbsp;د اليصفن قبيلې نه سمعياه، چې د دوو سوو کسانو مشر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10139, '1 Chronicles 15:9', '1 Chronicles', 15, 9, '&nbsp;د حبرون قبيلې نه اِلى‌ايل، چې د اتياو کسانو مشر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10140, '1 Chronicles 15:10', '1 Chronicles', 15, 10, '&nbsp;د عُزى‌اېل قبيلې نه عمى‌نداب، چې د خپلې قبيلې د يو سل او دولسو کسانو مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10141, '1 Chronicles 15:11', '1 Chronicles', 15, 11, '&nbsp;داؤد صدوق او ابياتار اِمامان او دا شپږ ليويان يې راوغوښتل: اورى‌اېل، عساياه، يوايل، سمعياه، اِلى‌ايل او عمى‌نداب.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10142, '1 Chronicles 15:12', '1 Chronicles', 15, 12, '&nbsp;هغۀ ورته وفرمائيل، ”تاسو د ليويانو قبيلې مشران يئ. خپل ځانونه او خپل ليويان پاک کړئ، نو چې تاسو د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک د لوظ صندوق هغه ځائ ته راوړئ چې ما ورله تيار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10143, '1 Chronicles 15:13', '1 Chronicles', 15, 13, '&nbsp;په وړومبى ځل تاسو دا رانۀ وړو، نو ځکه مالِک خُدائ زمونږ خُدائ پاک مونږ له سزا راکړې ده چې مونږ د هغۀ نه دا تپوس نۀ دے کړے چې څنګه يې يوسو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10144, '1 Chronicles 15:14', '1 Chronicles', 15, 14, '&nbsp;بيا اِمامانو او ليويانو د دې دپاره خپل ځانونه پاک کړل چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک د لوظ صندوق يروشلم ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10145, '1 Chronicles 15:15', '1 Chronicles', 15, 15, '&nbsp;ليويانو دا د بازوګانو په ذريعه په خپلو ولو باندې يوړو، لکه څنګه چې موسىٰ د مالِک خُدائ د حُکم په مطابق حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10146, '1 Chronicles 15:16', '1 Chronicles', 15, 16, '&nbsp;داؤد د ليويانو مشرانو له حُکم ورکړو چې څۀ ليويانو ته يې سندرې وئيل، او په بينجو، رباب او په چمټو باندې خوندوره موسيقى غږول حواله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10147, '1 Chronicles 15:22', '1 Chronicles', 15, 22, '&nbsp;په موسيقۍ کښې د مهارت په وجه کنعنياه د دې دپاره خوښ کړے شوے وو چې د ليوى موسيقارانو مشر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10148, '1 Chronicles 15:25', '1 Chronicles', 15, 25, '&nbsp;نو داؤد بادشاه، د بنى اِسرائيلو مشران او فوجى مشران د عوبيد ادوم کور ته لاړل چې د مالِک خُدائ د لوظ صندوق راوچت کړى. او هغوئ يو لوئ جشن جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10149, '1 Chronicles 15:26', '1 Chronicles', 15, 26, '&nbsp;هغوئ اووۀ غوَيى او اووۀ ګډان حلال کړل، چې دا خبره يقينى شى چې مالِک خُدائ به د هغه ليويانو سره مدد کوى چا چې د لوظ صندوق وړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10150, '1 Chronicles 15:27', '1 Chronicles', 15, 27, '&nbsp;داؤد د مهينې لټې نه جوړه شوې چُوغه اغوستې وه او موسيقارانو، د هغوئ مشر کنعنياه او هغه ليويانو هم د مهينې لټې چُوغې اغوستې وې چا چې صندوق وړلو. داؤد د لټې پېش بند هم اغوستے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10151, '1 Chronicles 15:28', '1 Chronicles', 15, 28, '&nbsp;نو داسې ټول بنى اِسرائيليان د لوظ صندوق سره يروشلم ته روان وُو. او د خوشحالۍ نه يې چغې وهلې، د بيګلو، ښکرو، چمټو او بينجو د موسيقۍ آوازونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10152, '1 Chronicles 15:29', '1 Chronicles', 15, 29, '&nbsp;کله چې د لوظ صندوق ښار ته راوړلے شو، نو په دې وخت کښې د ساؤل لور او د داؤد ښځې ميکل د کړکۍ نه بهر وکتل او وې ليدل چې داؤد بادشاه د خوشحالۍ نه ټوپونه وهل، نو هغې ورته په زړۀ کښې سپک وکتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10153, '1 Chronicles 16:1', '1 Chronicles', 16, 1, '&nbsp;هغوئ د لوظ صندوق هغه خېمې ته يوړو چې داؤد ورله تياره کړې وه او هغه يې په خېمه کښې دننه کېښودو. بيا هغوئ خُدائ پاک ته سوزېدونکې نذرانې او د سلامتۍ نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10154, '1 Chronicles 16:2', '1 Chronicles', 16, 2, '&nbsp;کله چې داؤد سوزېدونکې نذرانې او د سلامتۍ نذرانې پېش کول بس کړل، نو هغۀ د مالِک خُدائ په نوم باندې خلقو له برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10155, '1 Chronicles 16:3', '1 Chronicles', 16, 3, '&nbsp;بيا هغۀ په ټول بنى اِسرائيل کښې هر سړى او ښځې له يوه روټۍ، د غوښې يوه برخه او څۀ کشمش ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10156, '1 Chronicles 16:4', '1 Chronicles', 16, 4, '&nbsp;داؤد څۀ ليويان مقرر کړل چې د لوظ صندوق مخامخ د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک خِدمت وکړى او د هغۀ ثناء صِفت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10157, '1 Chronicles 16:5', '1 Chronicles', 16, 5, '&nbsp;آسف د هغوئ مشر وو او دا سړى د هغۀ مددګاران مقرر شُو: زکرياه، يعى‌ايل، سميراموت، يحى‌ايل، متتياه، اِلياب، بناياه، عوبيد ادوم او يعى‌ايل. هغوئ به بينجو غږولې. آسف چمټې غږولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10158, '1 Chronicles 16:6', '1 Chronicles', 16, 6, '&nbsp;او دې دوو اِمامانو بناياه او يحزى‌ايل به د لوظ صندوق په وړاندې هره ورځ بيګلې غږولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10159, '1 Chronicles 16:7', '1 Chronicles', 16, 7, '&nbsp;هم په هغه ورځ داؤد آسف او د هغۀ ليويانو له د مالِک خُدائ د ثناء صِفت کولو ذمه وارى ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10160, '1 Chronicles 16:8', '1 Chronicles', 16, 8, '&nbsp;د مالِک خُدائ شکريه ادا کړئ، د هغۀ د لويئ اِعلان وکړئ، قومونو ته ووايئ چې هغۀ څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10161, '1 Chronicles 16:9', '1 Chronicles', 16, 9, '&nbsp;د مالِک خُدائ حمد‌و‌ثناء ووايئ، د هغه عجيبه کارونو په حقله ووايئ چې هغۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10162, '1 Chronicles 16:10', '1 Chronicles', 16, 10, '&nbsp;په دې باندې خوشحالى وکړئ چې مونږ د هغۀ يُو، چې څوک د هغۀ طلب کوى هغه ټول دې خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10163, '1 Chronicles 16:11', '1 Chronicles', 16, 11, '&nbsp;د مالِک خُدائ او د هغۀ د طاقت لټون کوئ او هر وخت د هغۀ په حضور کښې اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10164, '1 Chronicles 16:14', '1 Chronicles', 16, 14, '&nbsp;هغه مالِک خُدائ زمونږ خُدائ پاک دے، د هغۀ حُکمونه د ټولې دُنيا دپاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10165, '1 Chronicles 16:15', '1 Chronicles', 16, 15, '&nbsp;د خُدائ پاک لوظ هيڅکله مۀ هېروئ، چې کوم د پېړو پېړو پورې نۀ ختمېدونکے لوظ دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10166, '1 Chronicles 16:16', '1 Chronicles', 16, 16, '&nbsp;کوم لوظ چې هغۀ د اِبراهيم سره کړے وو، هغه وعده چې هغۀ د اِسحاق سره کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10167, '1 Chronicles 16:17', '1 Chronicles', 16, 17, '&nbsp;مالِک خُدائ د يعقوب سره يو لوظ وکړو، هغه لوظ چې نۀ ختمېدونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10168, '1 Chronicles 16:18', '1 Chronicles', 16, 18, '&nbsp;هغۀ وفرمائيل، ”زۀ به تاسو له د کنعان مُلک درکړم، دا به ستاسو خپل ميراث شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10169, '1 Chronicles 16:19', '1 Chronicles', 16, 19, '&nbsp;د خُدائ پاک خلق په شمېر کښې کم وُو، چې د کنعان په مُلک کښې مسافر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10170, '1 Chronicles 16:20', '1 Chronicles', 16, 20, '&nbsp;هغوئ د يو مُلک نه بل مُلک ته سرګردانه ګرځېدل، د يوې بادشاهۍ نه بلې بادشاهۍ ته تلل راتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10171, '1 Chronicles 16:21', '1 Chronicles', 16, 21, '&nbsp;خو خُدائ پاک هيڅ څوک پرې نۀ ښودل چې د هغوئ سره بد سلوک وکړى، د هغوئ د حِفاظت دپاره هغۀ بادشاهانو له خبردارے ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10172, '1 Chronicles 16:22', '1 Chronicles', 16, 22, '&nbsp;”زما خوښ کړے شوو خِدمت کوونکو ته ضرر مۀ رسوئ، زما پېغمبرانو ته تکليف مۀ رسوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10173, '1 Chronicles 16:23', '1 Chronicles', 16, 23, '&nbsp;اے ټولې دُنيا، د مالِک خُدائ صِفت وکړئ، د هغه زېرى اِعلان هره ورځ کوئ چې هغه بچ کول کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10174, '1 Chronicles 16:24', '1 Chronicles', 16, 24, '&nbsp;قومونو ته د هغۀ د جلال اِعلان وکړئ، ټولو خلقو ته د هغۀ د عجيبه کارنامو بيان وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10175, '1 Chronicles 16:25', '1 Chronicles', 16, 25, '&nbsp;مالِک خُدائ لوئ دے او د هغۀ دې لوئى او ثناء صِفت وشى، د نورو ټولو خُدايانو نه دې د هغۀ زيات درناوے وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10176, '1 Chronicles 16:26', '1 Chronicles', 16, 26, '&nbsp;د نورو ټولو قومونو خُدايان تش بُتان دى، خو مالِک خُدائ آسمانونه پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10177, '1 Chronicles 16:27', '1 Chronicles', 16, 27, '&nbsp;د هغۀ نه ګېرچاپېره جلال او عزت دے، د هغۀ عبادتخانه د طاقت او د خوشحالۍ نه ډکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10178, '1 Chronicles 16:28', '1 Chronicles', 16, 28, '&nbsp;د زمکې ټولو قومونو، د مالِک خُدائ ثناء صِفت وکړئ، د هغۀ د جلال او د طاقت ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10179, '1 Chronicles 16:29', '1 Chronicles', 16, 29, '&nbsp;د مالِک خُدائ د ستائنې وړ نوم لوئى بيان کړئ، نذرانه راوړئ او د هغۀ حضور ته راشئ. کله چې هغه مقدسه هستى څرګنديږى نو د هغۀ په وړاندې سجده وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10180, '1 Chronicles 16:30', '1 Chronicles', 16, 30, '&nbsp;اے ټولې دُنيا، د هغۀ په مخکښې ورېږدېږئ. زمکه پخه لګولے شوې ده او نۀ شى خوځېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10181, '1 Chronicles 16:31', '1 Chronicles', 16, 31, '&nbsp;اے آسمانه او اے زمکې، خوشحالى وکړئ، قومونو ته ووايئ چې مالِک خُدائ بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10182, '1 Chronicles 16:32', '1 Chronicles', 16, 32, '&nbsp;سمندر او په هغې کښې مخلوق دې وغړمبيږى، پټى او په دې کښې هر څۀ دې خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10183, '1 Chronicles 16:33', '1 Chronicles', 16, 33, '&nbsp;د ځنګل ونې به د خوشحالۍ نه چغې ووهى. هغه وخت چې مالِک خُدائ په زمکه بادشاهۍ له راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10184, '1 Chronicles 16:34', '1 Chronicles', 16, 34, '&nbsp;د مالِک خُدائ شُکر ادا کړئ، ځکه چې هغه ښۀ دے، د هغۀ مينه نۀ ختمېدونکې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10185, '1 Chronicles 16:35', '1 Chronicles', 16, 35, '&nbsp;هغۀ ته ووايئ، ”اے زمونږ خلاصوونکيه خُدايه پاکه. مونږ بچ کړه، مونږ په يو ځائ راغونډ کړه، د قومونو نه مو بچ کړه، نو چې داسې مونږ شُکر ګزار شُو او ستا د پاک نوم ستائينه وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10186, '1 Chronicles 16:36', '1 Chronicles', 16, 36, '&nbsp;د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک ثناء صِفت وکړئ، د هغۀ ستائينه اوس او د همېشه دپاره کوئ.“ بيا ټولو خلقو ووئيل، ”د مالِک خُدائ ثناء صِفت دې وى، آمين.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10187, '1 Chronicles 16:37', '1 Chronicles', 16, 37, '&nbsp;داؤد بادشاه آسف او د هغۀ ملګرى ليويان د هرې ورځې د خِدمت دپاره مقرر کړل چې په هغه ځائ کښې کېدو چرته چې د لوظ صندوق کېښودلے شو. هغوئ به هلته هره ورځ خپلې ذمه وارۍ پوره کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10188, '1 Chronicles 16:38', '1 Chronicles', 16, 38, '&nbsp;د يدوتون زوئ عوبيد ادوم او د هغۀ د قبيلې اتۀ شپېتۀ سړو د هغوئ مدد کولو. حوسه او عوبيد ادوم د دروازو د څوکيدارۍ مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10189, '1 Chronicles 16:39', '1 Chronicles', 16, 39, '&nbsp;په دې دوران کښې، داؤد صدوق اِمام او د هغۀ ملګرى اِمامان د جبعون د عبادت په ځائ کښې د مالِک خُدائ په مقدسه خېمه کښې مقرر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10190, '1 Chronicles 16:40', '1 Chronicles', 16, 40, '&nbsp;هر سحر او هر ماښام به هغوئ په قربان‌ګاه باندې سوزېدونکې نذرانې پېش کولې. دا د هغه ليکلى قانون په مطابق وُو کوم چې مالِک خُدائ بنى اِسرائيلو له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10191, '1 Chronicles 16:41', '1 Chronicles', 16, 41, '&nbsp;هلته د هغوئ سره هيمان، يدوتون او نور کسان وُو چې کوم خصوصاً د مالِک خُدائ د نۀ ختمېدونکې مينې د ثناء صِفت کولو دپاره خوښ کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10192, '1 Chronicles 16:42', '1 Chronicles', 16, 42, '&nbsp;هيمان او يدوتون د بيګلو، چمټو او د موسيقۍ د نورو څيزونو مشرى هم کوله چې په هغه وخت کښې غږولے شول چې کله ثناء صِفت وئيلے شو. د يدوتون زامن د دروازې په څوکيدارۍ مقرر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10193, '1 Chronicles 16:43', '1 Chronicles', 16, 43, '&nbsp;نو بيا ټول خلق خپلو خپلو کورونو ته واپس شول او داؤد هم لاړو چې د خپل خاندان د برکت سبب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10194, '1 Chronicles 17:1', '1 Chronicles', 17, 1, '&nbsp;نو کله چې داؤد بادشاه په خپل محل کښې اوسېدو، يوه ورځ هغۀ ناتن پېغمبر راوغوښتو او ورته يې وفرمائيل، ”زۀ دلته په يو داسې ښائسته کور کښې اوسېږم چې د دِيار د لرګى نه جوړ دے، خو د مالِک خُدائ د لوظ صندوق په خېمه کښې پروت دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10195, '1 Chronicles 17:2', '1 Chronicles', 17, 2, '&nbsp;ناتن ورته وفرمائيل، ”ستا په زړۀ کښې چې څۀ وى نو هم هغه شان وکړه، ځکه چې خُدائ پاک ستا مل دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10196, '1 Chronicles 17:3', '1 Chronicles', 17, 3, '&nbsp;خو په هغه شپه د خُدائ پاک کلام په ناتن نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10197, '1 Chronicles 17:4', '1 Chronicles', 17, 4, '&nbsp;”لاړ شه او زما خِدمت کوونکى داؤد ته ووايه چې مالِک خُدائ داسې فرمائى چې تۀ هغه څوک نۀ يې چې زما د اوسېدو دپاره يو کور جوړ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10198, '1 Chronicles 17:5', '1 Chronicles', 17, 5, '&nbsp;د هغه وخت نه واخله چې ما بنى اِسرائيليان د مِصر نه راويستلى دى تر اوسه پورې، زۀ هيڅکله په يو کور کښې نۀ يم اوسېدلے، زۀ همېشه په يوه خېمه کښې اوسېدلے يم چې د يو ځائ نه به بل ځائ ته تلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10199, '1 Chronicles 17:6', '1 Chronicles', 17, 6, '&nbsp;ما چې د بنى اِسرائيلو سره څومره سفر هم کړے دے او چې ما څوک د خپلو خلقو د رهنمائى دپاره مقرر کړى دى ما د هغوئ يو کس ته هم نۀ دى وئيلى چې هغوئ زما دپاره د دِيار نه يو کور ولې نۀ دے جوړ کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10200, '1 Chronicles 17:7', '1 Chronicles', 17, 7, '&nbsp;نو زما خِدمت کوونکى داؤد ته ووايه چې زۀ ربُ الافواج هغۀ ته وايم چې ما تۀ په پټو کښې د ګډو د شپونتوب نه اوچت کړې او د خپلو خلقو بنى اِسرائيلو بادشاه مې جوړ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');